/* The manual and the task checks, generated by tools/mkcontent.c into content_gen.c from content/
 * (chapter texts and reference solutions, which stay out of the public repository).
 */
#ifndef MK1_CONTENT_H
#define MK1_CONTENT_H

#include <stdint.h>

#include "tasks.h"

typedef struct {
    const uint8_t *data;
    uint32_t len;
    uint8_t locked;   /* encrypted with the key of task <chapter number> */
} content_chapter;

extern const content_chapter CONTENT_CHAPTERS[];
extern const int CONTENT_N_CHAPTERS;
/* per task, per sample: 4 check bytes (see tasks.h) */
extern const uint8_t CONTENT_CHK[][TASK_MAX_SEGS][4];
extern const int CONTENT_N_TASKS;

#endif
